export interface Subscriber {
  id: string;
  name: string;
  email: string;
  active: boolean;
}

function copy(value: Subscriber): Subscriber {
  return {
    id: value.id,
    name: value.name,
    email: value.email,
    active: value.active,
  };
}

function seed(values: readonly Subscriber[]): Subscriber[] {
  const seen = new Set<string>();
  return values.map((value) => {
    if (value.id.length === 0) throw new RangeError("id must not be empty");
    if (seen.has(value.id)) throw new Error("duplicate subscriber");
    seen.add(value.id);
    return copy(value);
  });
}

export class SubscriberStore {
  private readonly v1: Subscriber[];
  private readonly v2: Subscriber[];

  constructor(v1: readonly Subscriber[] = [], v2: readonly Subscriber[] = []) {
    this.v1 = seed(v1);
    this.v2 = seed(v2);
  }

  list(): Subscriber[] {
    return this.v1.map(copy);
  }

  add(value: Subscriber): Subscriber {
    if (value.id.length === 0) throw new RangeError("id must not be empty");
    if (this.v2.some((item) => item.id === value.id)) {
      throw new Error("duplicate subscriber");
    }
    const stored = copy(value);
    this.v2.push(stored);
    return copy(stored);
  }

  remove(id: string): boolean {
    if (id.length === 0) throw new RangeError("id must not be empty");
    const index = this.v2.findIndex((item) => item.id === id);
    if (index < 0) return false;
    this.v2.splice(index, 1);
    return true;
  }

  update(value: Subscriber): Subscriber {
    if (value.id.length === 0) throw new RangeError("id must not be empty");
    const index = this.v2.findIndex((item) => item.id === value.id);
    if (index < 0) throw new Error("subscriber not found");
    this.v2[index] = copy(value);
    return copy(this.v2[index]);
  }
}

