import { SubscriberStore } from './solution';
import type { Subscriber } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

function throws(fn: () => unknown, ctor: Function, message?: string): void {
  try {
    fn();
  } catch (error) {
    assert(error instanceof (ctor as any), `wrong exception type: ${String(error)}`);
    if (message !== undefined) {
      assert((error as Error).message === message, `expected message ${message}, got ${(error as Error).message}`);
    }
    return;
  }
  throw new Error('expected function to throw');
}

const v1a: Subscriber = { id: 'v1-a', name: '', email: '', active: true };
const v1b: Subscriber = { id: 'v1-b', name: ' Beta ', email: ' b@example.test ', active: false };
const hiddenV1: Subscriber = { id: 'hidden-v1', name: 'Hidden V1', email: 'hidden-v1@example.test', active: true };
Object.defineProperty(hiddenV1, 'id', { enumerable: false });
const hiddenV2: Subscriber = { id: 'hidden-v2', name: 'Hidden V2', email: 'hidden-v2@example.test', active: false };
Object.defineProperty(hiddenV2, 'id', { enumerable: false });

const store = new SubscriberStore([v1a, v1b, hiddenV1], [hiddenV2]);
v1a.id = 'changed-source-v1';
v1b.name = 'changed-source-name';
hiddenV1.id = 'changed-hidden-v1';
hiddenV2.id = 'changed-hidden-v2';

const listed = store.list();
equal(listed, [
  { id: 'v1-a', name: '', email: '', active: true },
  { id: 'v1-b', name: ' Beta ', email: ' b@example.test ', active: false },
  { id: 'hidden-v1', name: 'Hidden V1', email: 'hidden-v1@example.test', active: true }
], 'list preserves V1 order, required fields, and constructor copies');
assert(listed[2].id === 'hidden-v1', 'list copies a non-enumerable V1 id');
assert(listed[2].name === 'Hidden V1', 'list preserves the hidden-id record name');
assert(listed[2].email === 'hidden-v1@example.test', 'list preserves the hidden-id record email');
assert(listed[2].active === true, 'list preserves the hidden-id record active value');

const hiddenUpdate: Subscriber = { id: 'hidden-v2', name: 'Updated hidden', email: 'updated@example.test', active: true };
for (const key of ['id', 'name', 'email', 'active'] as const) {
  Object.defineProperty(hiddenUpdate, key, { enumerable: false });
}
const hiddenUpdateResult = store.update(hiddenUpdate);
assert(hiddenUpdateResult !== hiddenUpdate, 'update result must not alias a hidden-field input');
assert(hiddenUpdateResult.id === 'hidden-v2', 'update reads and returns a non-enumerable id');
assert(hiddenUpdateResult.name === 'Updated hidden', 'update returns a non-enumerable name');
assert(hiddenUpdateResult.email === 'updated@example.test', 'update returns a non-enumerable email');
assert(hiddenUpdateResult.active === true, 'update returns a non-enumerable active value');
hiddenUpdate.id = 'changed-update-input';
hiddenUpdateResult.id = 'changed-update-result';
assert(store.remove('hidden-v2') === true, 'hidden V2 id remains stored after update input and result mutation');
assert(store.remove('hidden-v2') === false, 'remove reports a missing V2 entry');
assert(store.remove('v1-a') === false, 'remove must not operate on V1');

equal(store.list(), [
  { id: 'v1-a', name: '', email: '', active: true },
  { id: 'v1-b', name: ' Beta ', email: ' b@example.test ', active: false },
  { id: 'hidden-v1', name: 'Hidden V1', email: 'hidden-v1@example.test', active: true }
], 'V2 operations do not affect V1');

const firstList = store.list();
const secondList = store.list();
assert(firstList !== secondList, 'list arrays must be fresh');
assert(firstList[0] !== secondList[0], 'listed objects must be fresh');
firstList.reverse();
firstList[0].id = 'mutated-result';
assert(store.list()[0].id === 'v1-a', 'mutating a list result must not affect stored V1');

const addedInput: Subscriber = { id: 'new', name: '', email: '', active: false };
for (const key of ['id', 'name', 'email', 'active'] as const) {
  Object.defineProperty(addedInput, key, { enumerable: false });
}
const addedResult = store.add(addedInput);
assert(addedResult !== addedInput, 'add result must not alias its input');
assert(addedResult.id === 'new', 'add returns a non-enumerable input id');
assert(addedResult.name === '', 'add returns a non-enumerable empty name');
assert(addedResult.email === '', 'add returns a non-enumerable empty email');
assert(addedResult.active === false, 'add returns a non-enumerable active value');
addedInput.id = 'changed-input';
addedResult.id = 'changed-result';
throws(() => store.add({ id: 'new', name: 'duplicate', email: '', active: true }), Error, 'duplicate subscriber');
assert(store.remove('new') === true, 'add input and result mutations must not alter stored identity');

store.add({ id: 'up', name: 'before', email: 'before@example.test', active: false });
const updateInput: Subscriber = { id: 'up', name: '', email: '', active: true };
const updateResult = store.update(updateInput);
assert(updateResult !== updateInput, 'update result must not alias its input');
equal(updateResult, { id: 'up', name: '', email: '', active: true }, 'update preserves exact values');
updateInput.id = 'changed-update-input';
updateResult.id = 'changed-update-result';
assert(store.remove('up') === true, 'update input and result mutations must not alter stored identity');
throws(() => store.update({ id: 'missing', name: '', email: '', active: false }), Error, 'subscriber not found');

store.add({ id: ' ', name: '', email: '', active: true });
assert(store.remove(' ') === true, 'a non-empty whitespace id is accepted exactly');

throws(() => store.add({ id: '', name: '', email: '', active: true }), RangeError);
throws(() => store.update({ id: '', name: '', email: '', active: true }), RangeError);
throws(() => store.remove(''), RangeError);
throws(() => new SubscriberStore([{ id: '', name: '', email: '', active: true }]), RangeError);
throws(() => new SubscriberStore([], [{ id: '', name: '', email: '', active: true }]), RangeError);

const duplicateHidden: Subscriber = { id: 'same', name: 'two', email: '', active: false };
Object.defineProperty(duplicateHidden, 'id', { enumerable: false });
throws(() => new SubscriberStore([
  { id: 'same', name: 'one', email: '', active: true },
  duplicateHidden
]), Error, 'duplicate subscriber');
throws(() => new SubscriberStore([], [
  { id: 'same', name: 'one', email: '', active: true },
  duplicateHidden
]), Error, 'duplicate subscriber');

const independentNamespaces = new SubscriberStore(
  [{ id: 'shared', name: 'V1', email: '', active: true }],
  [{ id: 'shared', name: 'V2', email: '', active: false }]
);
equal(independentNamespaces.list(), [{ id: 'shared', name: 'V1', email: '', active: true }], 'the same id may exist in separate namespaces');
assert(independentNamespaces.remove('shared') === true, 'the V2 shared id is independently removable');
equal(independentNamespaces.list(), [{ id: 'shared', name: 'V1', email: '', active: true }], 'V2 removal does not affect V1');

