Implement a standard-library-only dimension ledger.

Export:

```ts
export interface Dimensions { width: number; height: number }
export type DimensionListener = (current: Readonly<Dimensions>) => void;
export class DimensionLedger {
  constructor(initial: Dimensions);
  current(): Dimensions;
  resize(next: Dimensions): boolean;
  onChange(listener: DimensionListener): () => void;
}
```

A dimension is valid only when both values are finite, non-negative integers; the constructor and `resize` throw `RangeError` otherwise, without changing state. Inputs and outputs must not alias internal state. `resize` returns false and emits nothing when both dimensions are unchanged. Otherwise it commits the new dimensions, calls listeners in registration order, and returns true. Notification uses a snapshot of registrations, so subscriptions and removals made during a callback affect only later resizes. Each listener receives a separate object. Duplicate registrations are independent, and removal functions are idempotent.

Return only the complete source file; do not include Markdown fences or prose.

export interface Dimensions {
  width: number;
  height: number;
}

export type DimensionListener = (current: Readonly<Dimensions>) => void;

function validate(value: Dimensions): void {
  if (
    !Number.isFinite(value.width) ||
    !Number.isFinite(value.height) ||
    !Number.isInteger(value.width) ||
    !Number.isInteger(value.height) ||
    value.width < 0 ||
    value.height < 0
  ) {
    throw new RangeError("dimensions must be finite non-negative integers");
  }
}

function copy(value: Dimensions): Dimensions {
  return { width: value.width, height: value.height };
}

export class DimensionLedger {
  private value: Dimensions;
  private readonly listeners: Array<{
    listener: DimensionListener;
    active: boolean;
  }> = [];

  constructor(initial: Dimensions) {
    validate(initial);
    this.value = copy(initial);
  }

  current(): Dimensions {
    return copy(this.value);
  }

  resize(next: Dimensions): boolean {
    validate(next);
    if (next.width === this.value.width && next.height === this.value.height) {
      return false;
    }
    this.value = copy(next);
    const current = this.listeners.filter((entry) => entry.active);
    for (const entry of current) {
      entry.listener(copy(this.value));
    }
    return true;
  }

  onChange(listener: DimensionListener): () => void {
    const entry = { listener, active: true };
    this.listeners.push(entry);
    return () => {
      entry.active = false;
    };
  }
}

