import { DimensionLedger } from './solution';
import type { Dimensions, DimensionListener } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

function rangeError(fn: () => unknown): void {
  try {
    fn();
  } catch (error) {
    assert(error instanceof RangeError, `expected RangeError, got ${String(error)}`);
    return;
  }
  throw new Error('expected RangeError');
}

const initial: Dimensions = { width: 0, height: Number.MAX_VALUE };
const ledger = new DimensionLedger(initial);
initial.width = 77;
initial.height = 88;
equal(ledger.current(), { width: 0, height: Number.MAX_VALUE }, 'constructor copies valid finite integer input');

const hiddenInitial: Dimensions = { width: 3, height: 4 };
Object.defineProperty(hiddenInitial, 'width', { enumerable: false });
Object.defineProperty(hiddenInitial, 'height', { enumerable: false });
const hiddenLedger = new DimensionLedger(hiddenInitial);
const hiddenCurrent = hiddenLedger.current();
assert(hiddenCurrent.width === 3, 'constructor reads a non-enumerable width');
assert(hiddenCurrent.height === 4, 'constructor reads a non-enumerable height');
hiddenInitial.width = 30;
hiddenInitial.height = 40;
assert(hiddenLedger.current().width === 3 && hiddenLedger.current().height === 4, 'hidden constructor fields are detached');

const currentA = ledger.current();
const currentB = ledger.current();
assert(currentA !== currentB, 'current returns a fresh object');
currentA.width = 12;
equal(ledger.current(), { width: 0, height: Number.MAX_VALUE }, 'current result does not alias state');

let unchangedCalls = 0;
ledger.onChange(() => { unchangedCalls += 1; });
assert(ledger.resize({ width: 0, height: Number.MAX_VALUE }) === false, 'unchanged resize returns false');
assert(unchangedCalls === 0, 'unchanged resize emits nothing');

const next: Dimensions = { width: 5, height: 6 };
const observations: string[] = [];
let firstObject: Readonly<Dimensions> | undefined;
let secondObject: Readonly<Dimensions> | undefined;
ledger.onChange((value) => {
  firstObject = value;
  observations.push(`first:${value.width}x${value.height}`);
  (value as Dimensions).width = 999;
});
ledger.onChange((value) => {
  secondObject = value;
  observations.push(`second:${value.width}x${value.height}`);
  equal(ledger.current(), { width: 5, height: 6 }, 'state is committed before notification');
});
assert(ledger.resize(next) === true, 'changed resize returns true');
next.width = 100;
next.height = 200;
equal(observations, ['first:5x6', 'second:5x6'], 'listeners run in registration order with isolated values');
assert(firstObject !== secondObject, 'each listener receives a separate object');
equal(ledger.current(), { width: 5, height: 6 }, 'listener and input mutations do not affect state');

const hiddenNext: Dimensions = { width: Number.MAX_SAFE_INTEGER + 1, height: Number.MAX_VALUE };
Object.defineProperty(hiddenNext, 'width', { enumerable: false });
Object.defineProperty(hiddenNext, 'height', { enumerable: false });
let hiddenNotification: Readonly<Dimensions> | undefined;
hiddenLedger.onChange((value) => { hiddenNotification = value; });
assert(hiddenLedger.resize(hiddenNext) === true, 'finite nonnegative integer values beyond the safe range are valid');
const hiddenAfterResize = hiddenLedger.current();
assert(hiddenAfterResize.width === Number.MAX_SAFE_INTEGER + 1, 'resize stores a non-enumerable width');
assert(hiddenAfterResize.height === Number.MAX_VALUE, 'resize stores a non-enumerable height');
assert(hiddenNotification !== undefined, 'changed hidden-field resize notifies listeners');
assert(hiddenNotification.width === Number.MAX_SAFE_INTEGER + 1, 'listener receives the hidden width value');
assert(hiddenNotification.height === Number.MAX_VALUE, 'listener receives the hidden height value');
hiddenNext.width = 1;
hiddenNext.height = 2;
assert(hiddenLedger.current().width === Number.MAX_SAFE_INTEGER + 1, 'hidden resize input does not alias state');

const snapshotLedger = new DimensionLedger({ width: 1, height: 1 });
const snapshotEvents: string[] = [];
let firstRun = true;
let removeB: () => void = () => {};
snapshotLedger.onChange(() => {
  snapshotEvents.push('A');
  removeB();
  if (firstRun) {
    firstRun = false;
    snapshotLedger.onChange(() => snapshotEvents.push('C'));
  }
});
removeB = snapshotLedger.onChange(() => snapshotEvents.push('B'));
snapshotLedger.resize({ width: 2, height: 2 });
equal(snapshotEvents, ['A', 'B'], 'registration changes during a callback affect only later resizes');
snapshotEvents.length = 0;
snapshotLedger.resize({ width: 3, height: 3 });
equal(snapshotEvents, ['A', 'C'], 'later resize uses updated registrations');

const duplicateLedger = new DimensionLedger({ width: 0, height: 0 });
let duplicateCalls = 0;
const duplicate: DimensionListener = () => { duplicateCalls += 1; };
const removeFirst = duplicateLedger.onChange(duplicate);
const removeSecond = duplicateLedger.onChange(duplicate);
removeFirst();
removeFirst();
duplicateLedger.resize({ width: 1, height: 0 });
assert(duplicateCalls === 1, 'duplicate registrations are independent and removal is idempotent');
removeSecond();
duplicateLedger.resize({ width: 2, height: 0 });
assert(duplicateCalls === 1, 'both duplicate registrations can be removed independently');

const invalids: Dimensions[] = [
  { width: -1, height: 0 },
  { width: 0, height: -1 },
  { width: 1.5, height: 0 },
  { width: 0, height: 2.5 },
  { width: Number.NaN, height: 0 },
  { width: 0, height: Number.POSITIVE_INFINITY },
  { width: Number.NEGATIVE_INFINITY, height: 0 }
];
for (const invalid of invalids) rangeError(() => new DimensionLedger(invalid));

const atomicLedger = new DimensionLedger({ width: 4, height: 7 });
let atomicCalls = 0;
atomicLedger.onChange(() => { atomicCalls += 1; });
for (const invalid of invalids) {
  rangeError(() => atomicLedger.resize(invalid));
  equal(atomicLedger.current(), { width: 4, height: 7 }, 'invalid resize does not change state');
}
assert(atomicCalls === 0, 'invalid resizes do not notify listeners');
assert(atomicLedger.resize({ width: Number.MAX_VALUE, height: Number.MAX_SAFE_INTEGER + 1 }) === true, 'large finite integer dimensions are valid');
equal(atomicLedger.current(), { width: Number.MAX_VALUE, height: Number.MAX_SAFE_INTEGER + 1 }, 'large valid dimensions are stored');

