import { groupPresets } from './solution';
import type { Preset, PresetGroups } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

function throwsType(fn: () => unknown, ctor: Function): void {
  try {
    fn();
  } catch (error) {
    assert(error instanceof (ctor as any), `wrong exception type: ${String(error)}`);
    return;
  }
  throw new Error('expected function to throw');
}

const empty: PresetGroups = groupPresets([]);
equal(empty, { available: [], withdrawn: [] }, 'empty input returns two empty groups');
assert(empty.available !== empty.withdrawn, 'empty groups are distinct arrays');

const p1: Preset = { id: 'z', label: 'a', status: 'available' };
const p2: Preset = { id: 'b', label: 'A', status: 'withdrawn' };
const p3: Preset = { id: 'a', label: 'a', status: 'available' };
const p4: Preset = { id: 'x', label: 'Z', status: 'withdrawn' };
const p5: Preset = { id: ' spaced ', label: ' Exact label ', status: 'available' };
const input: readonly Preset[] = [p1, p2, p3, p4, p5];
const original = input.map((value) => ({ ...value }));
const grouped = groupPresets(input);

equal(grouped, {
  available: [
    { id: ' spaced ', label: ' Exact label ', status: 'available' },
    { id: 'a', label: 'a', status: 'available' },
    { id: 'z', label: 'a', status: 'available' }
  ],
  withdrawn: [
    { id: 'b', label: 'A', status: 'withdrawn' },
    { id: 'x', label: 'Z', status: 'withdrawn' }
  ]
}, 'groups use status and ascending code-unit label and id order');
equal(input, original, 'input array and objects are not mutated');
assert(grouped.available[1] !== p3, 'available result objects are copies');
assert(grouped.withdrawn[0] !== p2, 'withdrawn result objects are copies');

grouped.available[0].id = 'changed';
grouped.withdrawn.reverse();
equal(input, original, 'mutating returned groups cannot affect inputs');
const regrouped = groupPresets(input);
assert(regrouped.available !== grouped.available, 'each call returns fresh group arrays');
assert(regrouped.available[0] !== grouped.available[0], 'each call returns fresh preset objects');

const hiddenLabel: Preset = { id: 'a-hidden-label', label: 'A', status: 'available' };
Object.defineProperty(hiddenLabel, 'label', { enumerable: false });
const hiddenId: Preset = { id: 'Z-hidden-id', label: 'same', status: 'available' };
Object.defineProperty(hiddenId, 'id', { enumerable: false });
const hiddenStatus: Preset = { id: 'w-hidden-status', label: 'A', status: 'withdrawn' };
Object.defineProperty(hiddenStatus, 'status', { enumerable: false });
const compoundInput: readonly Preset[] = [
  { id: 'z', label: 'same', status: 'available' },
  { id: 'a', label: 'same', status: 'available' },
  hiddenId,
  { id: 'first-z', label: 'Z', status: 'available' },
  hiddenLabel,
  { id: 'w-z', label: 'same', status: 'withdrawn' },
  { id: 'w-a', label: 'same', status: 'withdrawn' },
  hiddenStatus
];
const compound = groupPresets(compoundInput);
assert(compound.available.length === 5, 'all available records are grouped');
assert(compound.available[0].id === 'a-hidden-label', 'hidden label participates in primary sorting');
assert(compound.available[0].label === 'A', 'hidden label is copied into the result');
assert(compound.available[0].status === 'available', 'available status is retained');
assert(compound.available[1].id === 'first-z' && compound.available[1].label === 'Z', 'code-unit label ordering is used');
assert(compound.available[2].id === 'Z-hidden-id', 'hidden id participates in id tie-breaking');
assert(compound.available[3].id === 'a', 'lowercase id follows uppercase id for an equal label');
assert(compound.available[4].id === 'z', 'remaining equal-label id is ordered last');
assert(compound.available[2].label === 'same' && compound.available[2].status === 'available', 'hidden-id record retains every required field');
assert(compound.withdrawn.length === 3, 'all withdrawn records are grouped');
assert(compound.withdrawn[0].id === 'w-hidden-status', 'hidden status is read and grouped');
assert(compound.withdrawn[0].label === 'A' && compound.withdrawn[0].status === 'withdrawn', 'hidden-status record retains required fields');
assert(compound.withdrawn[1].id === 'w-a' && compound.withdrawn[2].id === 'w-z', 'withdrawn ties use ascending code-unit id order');
assert(compound.available[0] !== hiddenLabel, 'hidden-field result record is a copy');
assert(compound.available[2] !== hiddenId, 'hidden-id result record is a copy');
assert(compound.withdrawn[0] !== hiddenStatus, 'hidden-status result record is a copy');

for (const preset of [
  { id: '', label: 'valid', status: 'available' as const },
  { id: '   ', label: 'valid', status: 'withdrawn' as const },
  { id: 'valid', label: '', status: 'available' as const },
  { id: 'valid', label: '\t\n', status: 'withdrawn' as const }
]) {
  throwsType(() => groupPresets([preset]), TypeError);
}

const hiddenDuplicate: Preset = { id: 'duplicate', label: 'Two', status: 'withdrawn' };
Object.defineProperty(hiddenDuplicate, 'id', { enumerable: false });
throwsType(() => groupPresets([
  { id: 'duplicate', label: 'One', status: 'available' },
  hiddenDuplicate
]), RangeError);

const caseDistinct = groupPresets([
  { id: 'A', label: 'one', status: 'available' },
  { id: 'a', label: 'two', status: 'available' }
]);
assert(caseDistinct.available.length === 2, 'duplicate identity is exact and case-sensitive');

