import { addBook } from './solution';
import type { BookInput, Book, AddBookResult } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

const visibleBook: Book = {
  id: 'old-1', ownerId: 'owner-a', title: ' First ', author: 'Author 1', publishedYear: 2000, genre: 'Genre 1'
};
const hiddenBook: Book = {
  id: 'hidden-id', ownerId: 'hidden-owner', title: 'Hidden Title', author: 'Hidden Author', publishedYear: 1988, genre: 'Hidden Genre'
};
for (const key of ['id', 'ownerId', 'title', 'author', 'publishedYear', 'genre'] as const) {
  Object.defineProperty(hiddenBook, key, { enumerable: false });
}
const duplicateBook: Book = {
  id: 'dup', ownerId: 'owner-b', title: 'Second', author: 'Author 2', publishedYear: 1999, genre: 'Genre 2'
};
const existing: Book[] = [visibleBook, hiddenBook, duplicateBook];
const expectedExisting: Book[] = [
  { id: 'old-1', ownerId: 'owner-a', title: ' First ', author: 'Author 1', publishedYear: 2000, genre: 'Genre 1' },
  { id: 'hidden-id', ownerId: 'hidden-owner', title: 'Hidden Title', author: 'Hidden Author', publishedYear: 1988, genre: 'Hidden Genre' },
  { id: 'dup', ownerId: 'owner-b', title: 'Second', author: 'Author 2', publishedYear: 1999, genre: 'Genre 2' }
];
const input: BookInput = { title: '  New Title  ', author: '\tNew Author\n', publishedYear: 1450, genre: '  History  ' };
const inputSnapshot: BookInput = { ...input };
const success: AddBookResult = addBook(existing, '  owner-new  ', '  new-id  ', input);

assert(success.ok === true, 'valid book succeeds');
if (success.ok) {
  equal(success.books, [
    ...expectedExisting,
    { id: 'new-id', ownerId: 'owner-new', title: 'New Title', author: 'New Author', publishedYear: 1450, genre: 'History' }
  ], 'success preserves existing content and order and appends the trimmed new book');
  equal(success.book, { id: 'new-id', ownerId: 'owner-new', title: 'New Title', author: 'New Author', publishedYear: 1450, genre: 'History' }, 'success returns the added book');
  assert(success.books !== existing, 'success books array is fresh');
  assert(success.books[0] !== existing[0] && success.books[1] !== existing[1] && success.books[2] !== existing[2], 'success copies every existing book');
  const copiedHidden = success.books[1];
  assert(copiedHidden.id === 'hidden-id', 'success copies a non-enumerable existing id');
  assert(copiedHidden.ownerId === 'hidden-owner', 'success copies a non-enumerable existing ownerId');
  assert(copiedHidden.title === 'Hidden Title', 'success copies a non-enumerable existing title');
  assert(copiedHidden.author === 'Hidden Author', 'success copies a non-enumerable existing author');
  assert(copiedHidden.publishedYear === 1988, 'success copies a non-enumerable existing publishedYear');
  assert(copiedHidden.genre === 'Hidden Genre', 'success copies a non-enumerable existing genre');
  assert(success.book !== success.books[success.books.length - 1], 'success book does not alias the appended array entry');
  success.books[0].title = 'mutated-copy';
  success.books[1].id = 'mutated-hidden-copy';
  success.books[3].title = 'mutated-entry';
  success.book.title = 'mutated-book';
}
assert(visibleBook.title === ' First ', 'success does not mutate a visible existing book');
assert(hiddenBook.id === 'hidden-id' && hiddenBook.title === 'Hidden Title', 'success does not mutate a hidden-field existing book');
assert(duplicateBook.id === 'dup', 'success does not mutate later existing books');
equal(input, inputSnapshot, 'success does not mutate BookInput');

const upper = addBook([], 'owner', 'upper', { title: 'T', author: 'A', publishedYear: 2100, genre: 'G' });
assert(upper.ok === true, 'publishedYear 2100 is valid');
const lower = addBook([], 'owner', 'lower', { title: 'T', author: 'A', publishedYear: 1450, genre: 'G' });
assert(lower.ok === true, 'publishedYear 1450 is valid');

const allInvalid = addBook(existing, ' \t ', '\n', {
  title: '',
  author: '   ',
  publishedYear: 1449,
  genre: '\t'
});
assert(allInvalid.ok === false, 'invalid fields fail');
if (!allInvalid.ok) {
  equal(allInvalid.errors, ['ownerId', 'id', 'title', 'author', 'publishedYear', 'genre'], 'validation errors use the required order');
  equal(allInvalid.books, expectedExisting, 'failure preserves existing book content and order');
  assert(allInvalid.books !== existing, 'failure books array is fresh');
  assert(allInvalid.books[0] !== existing[0] && allInvalid.books[1] !== existing[1] && allInvalid.books[2] !== existing[2], 'failure copies every existing book');
  const copiedHidden = allInvalid.books[1];
  assert(copiedHidden.id === 'hidden-id', 'failure copies a non-enumerable existing id');
  assert(copiedHidden.ownerId === 'hidden-owner', 'failure copies a non-enumerable existing ownerId');
  assert(copiedHidden.title === 'Hidden Title', 'failure copies a non-enumerable existing title');
  assert(copiedHidden.author === 'Hidden Author', 'failure copies a non-enumerable existing author');
  assert(copiedHidden.publishedYear === 1988, 'failure copies a non-enumerable existing publishedYear');
  assert(copiedHidden.genre === 'Hidden Genre', 'failure copies a non-enumerable existing genre');
  allInvalid.books[1].title = 'mutated-failure-copy';
}
assert(hiddenBook.title === 'Hidden Title', 'mutating a failure result does not affect hidden input fields');

const duplicateAndInvalid = addBook(existing, 'owner', ' dup ', {
  title: ' ',
  author: 'Author',
  publishedYear: 2101,
  genre: ''
});
assert(duplicateAndInvalid.ok === false, 'duplicate and field errors are collected together');
if (!duplicateAndInvalid.ok) {
  equal(duplicateAndInvalid.errors, ['title', 'publishedYear', 'genre', 'duplicateId'], 'duplicateId follows field errors and uses the trimmed candidate id');
}

const hiddenDuplicate = addBook(existing, 'owner', ' hidden-id ', {
  title: 'Title', author: 'Author', publishedYear: 2001, genre: 'Genre'
});
assert(hiddenDuplicate.ok === false, 'a non-enumerable existing id participates in duplicate detection');
if (!hiddenDuplicate.ok) {
  equal(hiddenDuplicate.errors, ['duplicateId'], 'hidden existing id reports duplicateId');
}

for (const value of [1450.5, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY, Number.MAX_SAFE_INTEGER]) {
  const result = addBook([], 'owner', `id-${String(value)}`, {
    title: 'Title', author: 'Author', publishedYear: value, genre: 'Genre'
  });
  assert(result.ok === false, `publishedYear ${String(value)} fails`);
  if (!result.ok) equal(result.errors, ['publishedYear'], 'invalid year reports only publishedYear');
}

const exactIdentity = addBook(existing, 'owner', 'DUP', {
  title: 'Title', author: 'Author', publishedYear: 2001, genre: 'Genre'
});
assert(exactIdentity.ok === true, 'duplicate id matching is exact and case-sensitive');

const failureOne = addBook(existing, 'owner', 'dup', {
  title: 'Title', author: 'Author', publishedYear: 2001, genre: 'Genre'
});
const failureTwo = addBook(existing, 'owner', 'dup', {
  title: 'Title', author: 'Author', publishedYear: 2001, genre: 'Genre'
});
assert(!failureOne.ok && !failureTwo.ok, 'duplicate calls fail');
if (!failureOne.ok && !failureTwo.ok) {
  assert(failureOne.books !== failureTwo.books, 'separate failures return separate arrays');
  assert(failureOne.books[0] !== failureTwo.books[0], 'separate failures return separate book objects');
  equal(failureOne.errors, ['duplicateId'], 'a valid duplicate reports duplicateId only');
}

