'use strict';

function createGlossary(entries) {
  if (!Array.isArray(entries)) throw new TypeError('entries must be an array');
  const glossary = new Map();

  for (let i = 0; i < entries.length; i += 1) {
    const entry = entries[i];
    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) {
      throw new TypeError('entry must be an object');
    }
    if (typeof entry.term !== 'string' || entry.term.trim() === '') {
      throw new TypeError('term must be a nonempty string');
    }
    if (!Array.isArray(entry.categories)) {
      throw new TypeError('categories must contain nonempty strings');
    }

    const categories = [];
    for (let j = 0; j < entry.categories.length; j += 1) {
      const category = entry.categories[j];
      if (typeof category !== 'string' || category.trim() === '') {
        throw new TypeError('categories must contain nonempty strings');
      }
      categories.push(category.trim());
    }

    const term = entry.term.trim();
    const key = term.toLowerCase();
    if (glossary.has(key)) throw new Error(`Duplicate term: ${term}`);
    glossary.set(key, { canonical: term, categories });
  }

  function review(tokens) {
    if (!Array.isArray(tokens)) throw new TypeError('tokens must be an array of strings');
    const results = [];
    for (let i = 0; i < tokens.length; i += 1) {
      const token = tokens[i];
      if (typeof token !== 'string') {
        throw new TypeError('tokens must be an array of strings');
      }
      const found = glossary.get(token.toLowerCase());
      results.push(found
        ? { token, known: true, canonical: found.canonical, categories: [...found.categories] }
        : { token, known: false, canonical: null, categories: [] });
    }
    return results;
  }

  return { review };
}

module.exports = { createGlossary };

