'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['createGlossary']);
assert.strictEqual(typeof api.createGlossary, 'function');
const { createGlossary } = api;

assert.throws(() => createGlossary(), TypeError);
assert.throws(() => createGlossary({}), TypeError);
assert.throws(() => createGlossary([null]), TypeError);
assert.throws(() => createGlossary([{}]), TypeError);
assert.throws(() => createGlossary([{ term: '', categories: [] }]), TypeError);
assert.throws(() => createGlossary([{ term: '   ', categories: [] }]), TypeError);
assert.throws(() => createGlossary([{ term: 'ok', categories: 'x' }]), TypeError);
assert.throws(() => createGlossary([{ term: 'ok', categories: [''] }]), TypeError);
assert.throws(() => createGlossary([{ term: 'ok', categories: ['  '] }]), TypeError);
assert.throws(() => createGlossary([{ term: 'ok', categories: [3] }]), TypeError);
assert.throws(() => createGlossary([{ term: 'ok', categories: new Array(1) }]), TypeError);
assert.throws(() => createGlossary([{ term: 'ok', categories: ['valid', ,] }]), TypeError);
assert.throws(
  () => createGlossary([
    { term: ' Alpha ', categories: [] },
    { term: ' ALPHA ', categories: [] }
  ]),
  err => err instanceof Error && err.message === 'Duplicate term: ALPHA'
);

const sourceCategories = [' Core ', 'API'];
const sourceEntry = { term: ' Alpha ', categories: sourceCategories };
const entries = [
  sourceEntry,
  { term: 'beta', categories: [] }
];
