  { token: 'beta', known: true, canonical: 'beta', categories: [] },
  { token: 'missing', known: false, canonical: null, categories: [] },
  { token: '', known: false, canonical: null, categories: [] },
  { token: ' Alpha ', known: false, canonical: null, categories: [] }
]);

results[0].canonical = 'corrupt';
results[0].categories[0] = 'corrupt';
results[1].categories.push('corrupt');
results[3].categories.push('corrupt');
tokens[0] = 'missing';
assert.deepStrictEqual(glossary.review(['alpha', 'missing']), [
  { token: 'alpha', known: true, canonical: 'Alpha', categories: ['Core', 'API'] },
  { token: 'missing', known: false, canonical: null, categories: [] }
]);

const repeated = glossary.review(['alpha', 'alpha']);
repeated[0].categories[0] = 'changed';
assert.deepStrictEqual(repeated[1], {
  token: 'alpha', known: true, canonical: 'Alpha', categories: ['Core', 'API']
});

const empty = createGlossary([]);
assert.deepStrictEqual(empty.review(['anything', '']), [
  { token: 'anything', known: false, canonical: null, categories: [] },
