'use strict';

function splitEpochNanos(value) {
  let nanos;
  if (typeof value === 'bigint') nanos = value;
  else if (typeof value === 'string' && /^\d+$/.test(value)) nanos = BigInt(value);
  else throw new TypeError('value must be a non-negative bigint or decimal string');

  if (nanos < 0n) throw new RangeError('value must be non-negative');
  const milliseconds = nanos / 1000000n;
  if (milliseconds > BigInt(Number.MAX_SAFE_INTEGER)) {
    throw new RangeError('millisecond component is too large');
  }
  return {
    epochMilliseconds: Number(milliseconds),
    remainderNanoseconds: Number(nanos % 1000000n)
  };
}

function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function validateMeasurement(value) {
  if (!isRecord(value) ||
      typeof value.device !== 'string' || value.device.length === 0 ||
      typeof value.metric !== 'string' || value.metric.length === 0 ||
      typeof value.value !== 'number' || !Number.isFinite(value.value)) {
    throw new TypeError('invalid measurement');
  }
  try {
    return splitEpochNanos(value.atNanos);
  } catch (error) {
    throw new TypeError('invalid measurement');
  }
}

class FeedMapper {
  constructor(useModernProtocol) {
    this.useModernProtocol = Boolean(useModernProtocol);
  }

  _measurements(packet) {
    if (!isRecord(packet)) throw new TypeError('invalid packet');
    const singular = this.useModernProtocol ? 'sample' : 'reading';
    const plural = this.useModernProtocol ? 'samples' : 'readings';
    if (packet.kind !== singular && packet.kind !== plural) {
      throw new TypeError('unsupported packet');
    }
