'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api).sort(), ['FeedMapper', 'splitEpochNanos']);
const { splitEpochNanos, FeedMapper } = api;
assert.strictEqual(typeof splitEpochNanos, 'function');
assert.strictEqual(typeof FeedMapper, 'function');

assert.deepStrictEqual(splitEpochNanos(0n), {
  epochMilliseconds: 0,
  remainderNanoseconds: 0
});
assert.deepStrictEqual(splitEpochNanos('0000001000001'), {
  epochMilliseconds: 1,
  remainderNanoseconds: 1
});
assert.deepStrictEqual(splitEpochNanos(1234567890n), {
  epochMilliseconds: 1234,
  remainderNanoseconds: 567890
});

const maxMs = BigInt(Number.MAX_SAFE_INTEGER);
const largestAccepted = maxMs * 1000000n + 999999n;
assert.deepStrictEqual(splitEpochNanos(largestAccepted), {
  epochMilliseconds: Number.MAX_SAFE_INTEGER,
  remainderNanoseconds: 999999
});
assert.throws(() => splitEpochNanos((maxMs + 1n) * 1000000n), RangeError);
assert.throws(() => splitEpochNanos('-1'));
assert.throws(() => splitEpochNanos(-1n));
for (const invalid of ['', ' ', '+1', '1.0', '1e6', '12x', 1, null, undefined, {}, true]) {
  assert.throws(() => splitEpochNanos(invalid), TypeError);
}

const legacy = new FeedMapper(false);
const modern = new FeedMapper(true);

assert.strictEqual(legacy.canHandle({ kind: 'reading', data: { device: 'd', metric: 'm', value: 1, atNanos: 0n } }), true);
assert.strictEqual(legacy.canHandle({ kind: 'readings', data: [] }), true);
assert.strictEqual(legacy.canHandle({ kind: 'sample', data: { device: 'd', metric: 'm', value: 1, atNanos: 0n } }), false);
assert.strictEqual(modern.canHandle({ kind: 'sample', data: { device: 'd', metric: 'm', value: 1, atNanos: 0n } }), true);
assert.strictEqual(modern.canHandle({ kind: 'samples', data: [] }), true);
assert.strictEqual(modern.canHandle({ kind: 'reading', data: { device: 'd', metric: 'm', value: 1, atNanos: 0n } }), false);
for (const malformed of [null, undefined, 4, 'reading', {}, { kind: null }, { kind: 'unknown' }]) {
  assert.doesNotThrow(() => {
    assert.strictEqual(typeof legacy.canHandle(malformed), 'boolean');
  });
}

const validMeasurement = { device: 'd', metric: 'm', value: 1, atNanos: 0n };
const oneHoleData = new Array(1);
const trailingHoleData = [validMeasurement, ,];
assert.strictEqual(legacy.canHandle({ kind: 'readings', data: oneHoleData }), false);
assert.strictEqual(legacy.canHandle({ kind: 'readings', data: trailingHoleData }), false);

assert.deepStrictEqual(legacy.getTopics([]), []);
assert.deepStrictEqual(legacy.getTopics(['a', 'b', 'a', 'A', 'b']), [
  'legacy/a', 'legacy/b', 'legacy/A'
]);
assert.deepStrictEqual(modern.getTopics(['dev', 'dev']), ['modern/dev']);
for (const invalid of [null, {}, 'dev', [null], [''], ['ok', '']]) {
  assert.throws(() => legacy.getTopics(invalid), TypeError);
}
const devices = ['one', 'two', 'one'];
const topics = modern.getTopics(devices);
devices[0] = 'changed';
topics[0] = 'changed';
assert.deepStrictEqual(modern.getTopics(['one', 'two', 'one']), ['modern/one', 'modern/two']);

const first = { device: 'd1', metric: 'temp', value: 1.5, atNanos: '1000001' };
const second = { device: 'd2', metric: 'load', value: -2, atNanos: 2999999n };
const packet = { kind: 'readings', data: [first, second] };
const mapped = Array.from(legacy.map(packet, Number.MAX_SAFE_INTEGER));
assert.deepStrictEqual(mapped, [
  {
    device: 'd1', metric: 'temp', value: 1.5,
    timestamp: { epochMilliseconds: 1, remainderNanoseconds: 1 },
    receivedSequence: Number.MAX_SAFE_INTEGER
  },
  {
    device: 'd2', metric: 'load', value: -2,
    timestamp: { epochMilliseconds: 2, remainderNanoseconds: 999999 },
    receivedSequence: Number.MAX_SAFE_INTEGER
  }
]);
assert.deepStrictEqual(packet.data, [first, second]);
mapped[0].device = 'changed';
mapped[0].timestamp.epochMilliseconds = 999;
assert.strictEqual(first.device, 'd1');
assert.deepStrictEqual(Array.from(legacy.map({ kind: 'reading', data: first }, 0)), [{
  device: 'd1', metric: 'temp', value: 1.5,
  timestamp: { epochMilliseconds: 1, remainderNanoseconds: 1 },
  receivedSequence: 0
}]);
assert.deepStrictEqual(Array.from(modern.map({ kind: 'samples', data: [] }, 1)), []);

for (const sequence of [-1, 1.5, Number.MAX_SAFE_INTEGER + 1, '1', null]) {
  assert.throws(() => Array.from(legacy.map({ kind: 'readings', data: [] }, sequence)), TypeError);
}
