  null,
  {},
  { kind: 'sample', data: first },
  { kind: 'reading' },
  { kind: 'reading', data: [first] },
  { kind: 'readings', data: first },
  { kind: 'readings', data: [first, null] },
  { kind: 'reading', data: { device: '', metric: 'm', value: 1, atNanos: 0n } },
  { kind: 'reading', data: { device: 'd', metric: '', value: 1, atNanos: 0n } },
  { kind: 'reading', data: { device: 'd', metric: 'm', value: Infinity, atNanos: 0n } },
  { kind: 'reading', data: { device: 'd', metric: 'm', value: NaN, atNanos: 0n } },
  { kind: 'reading', data: { device: 'd', metric: 'm', value: 1, atNanos: '' } }
]) {
  assert.throws(() => Array.from(legacy.map(badPacket, 0)), TypeError);
}

const oneHoleIterator = legacy.map({ kind: 'readings', data: new Array(1) }, 0);
assert.throws(() => oneHoleIterator.next(), TypeError);

const trailingHoleIterator = legacy.map({ kind: 'readings', data: [first, ,] }, 0);
assert.throws(() => trailingHoleIterator.next(), TypeError);

const partlyInvalid = {
  kind: 'readings',
  data: [first, { device: 'd', metric: '', value: 1, atNanos: 0n }]
};
const partlyInvalidIterator = legacy.map(partlyInvalid, 2);
assert.throws(() => partlyInvalidIterator.next(), TypeError);

