assert.throws(() => createRecipeBook([{ id: 'a', title: ' ', ingredients: [] }]), TypeError);
assert.throws(() => createRecipeBook([{ id: 'a', title: 'A', ingredients: 'salt' }]), TypeError);
assert.throws(() => createRecipeBook([{ id: 'a', title: 'A', ingredients: [''] }]), TypeError);
assert.throws(() => createRecipeBook([{ id: 'a', title: 'A', ingredients: ['  '] }]), TypeError);
