  { id: ' one ', title: 'First', ingredients: [] },
  { id: 'one', title: 'Second', ingredients: [] }
]), RangeError);

const ingredients = [' Flour ', ' Water '];
const original = { id: ' bread ', title: ' Basic Bread ', ingredients, ignored: true };
const initial = [
  original,
  { id: 'empty', title: 'No Ingredients', ingredients: [] }
];
