assert.deepStrictEqual(Object.keys(book).sort(), ['add', 'get', 'list', 'remove', 'update']);

original.id = 'changed';
original.title = 'Changed';
ingredients[0] = 'Poison';
ingredients.push('Extra');
initial[1] = null;
initial.push({ id: 'later', title: 'Later', ingredients: [] });

assert.deepStrictEqual(book.list(), [
  { id: 'bread', title: 'Basic Bread', ingredients: ['Flour', 'Water'] },
  { id: 'empty', title: 'No Ingredients', ingredients: [] }
]);
assert.deepStrictEqual(book.get(' bread '), {
  id: 'bread', title: 'Basic Bread', ingredients: ['Flour', 'Water']
});
assert.strictEqual(book.get('missing'), null);
for (const badId of ['', '   ', null, 1]) assert.throws(() => book.get(badId), TypeError);

const fetched = book.get('bread');
fetched.title = 'Corrupt';
fetched.ingredients[0] = 'Corrupt';
const listed = book.list();
listed[0].ingredients.push('Corrupt');
assert.deepStrictEqual(book.get('bread'), {
  id: 'bread', title: 'Basic Bread', ingredients: ['Flour', 'Water']
});

const addIngredients = [' Egg ', ' Milk '];
const addInput = { id: ' cake ', title: ' Cake ', ingredients: addIngredients, extra: 1 };
const added = book.add(addInput);
assert.deepStrictEqual(added, { id: 'cake', title: 'Cake', ingredients: ['Egg', 'Milk'] });
addInput.title = 'Changed';
addIngredients[0] = 'Changed';
added.ingredients[1] = 'Changed';
assert.deepStrictEqual(book.get('cake'), {
  id: 'cake', title: 'Cake', ingredients: ['Egg', 'Milk']
});
