assert.throws(() => book.add({ id: 'bad', title: '', ingredients: [] }), TypeError);
assert.strictEqual(book.get('bad'), null);
assert.throws(() => book.add({ id: 'sparse', title: 'Sparse', ingredients: new Array(1) }), TypeError);
assert.strictEqual(book.get('sparse'), null);
assert.throws(() => book.add({ id: 'trailing', title: 'Trailing', ingredients: ['Salt', ,] }), TypeError);
assert.strictEqual(book.get('trailing'), null);

assert.deepStrictEqual(book.update('bread', {}), {
  id: 'bread', title: 'Basic Bread', ingredients: ['Flour', 'Water']
});
const replacementIngredients = [' Yeast ', ' Salt '];
