  title: ' Better Bread ',
  ingredients: replacementIngredients
});
assert.deepStrictEqual(updated, {
  id: 'bread', title: 'Better Bread', ingredients: ['Yeast', 'Salt']
});
replacementIngredients[0] = 'Changed';
updated.ingredients[1] = 'Changed';
assert.deepStrictEqual(book.get('bread'), {
  id: 'bread', title: 'Better Bread', ingredients: ['Yeast', 'Salt']
});

assert.deepStrictEqual(book.update('empty', { ingredients: [] }), {
  id: 'empty', title: 'No Ingredients', ingredients: []
});
assert.throws(() => book.update('bread', { id: 'new-id' }), TypeError);
assert.throws(() => book.update('bread', null), TypeError);
assert.throws(() => book.update('bread', []), TypeError);
assert.throws(() => book.update('bread', { title: 'Valid', ingredients: [''] }), TypeError);
assert.deepStrictEqual(book.get('bread'), {
  id: 'bread', title: 'Better Bread', ingredients: ['Yeast', 'Salt']
});
assert.throws(() => book.update('unknown', { title: '' }), TypeError);
assert.throws(() => book.update('unknown', { ingredients: 'bad' }), TypeError);
assert.strictEqual(book.update('unknown', { title: 'Valid' }), null);

assert.throws(() => book.update('bread', {
  title: 'Must Not Apply',
  ingredients: ['Valid', ,]
}), TypeError);
assert.deepStrictEqual(book.get('bread'), {
  id: 'bread', title: 'Better Bread', ingredients: ['Yeast', 'Salt']
});

assert.strictEqual(book.remove(' cake '), true);
assert.strictEqual(book.remove('cake'), false);
assert.strictEqual(book.get('cake'), null);
assert.throws(() => book.remove(' '), TypeError);
assert.throws(() => book.remove(1), TypeError);
