#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EvalError {
    EmptyExpression,
    UnexpectedToken(usize),
    MissingClosingParen,
    DivisionByZero,
    Overflow,
}

pub fn evaluate(source: &str) -> Result<i64, EvalError> {
    let mut parser = Parser {
        source: source.as_bytes(),
        position: 0,
    };
    parser.skip_space();
    if parser.position == parser.source.len() {
        return Err(EvalError::EmptyExpression);
    }
    let value = parser.parse_sum()?;
    parser.skip_space();
    if parser.position != parser.source.len() {
        return Err(EvalError::UnexpectedToken(parser.position));
    }
    Ok(value)
}

struct Parser<'a> {
    source: &'a [u8],
    position: usize,
}

impl Parser<'_> {
    fn skip_space(&mut self) {
        while self
            .source
            .get(self.position)
            .is_some_and(|byte| byte.is_ascii_whitespace())
        {
            self.position += 1;
        }
    }

    fn take(&mut self, expected: u8) -> bool {
        self.skip_space();
        if self.source.get(self.position) == Some(&expected) {
            self.position += 1;
            true
        } else {
            false
        }
    }

    fn parse_sum(&mut self) -> Result<i64, EvalError> {
        let mut value = self.parse_product()?;
        loop {
            if self.take(b'+') {
                value = value
                    .checked_add(self.parse_product()?)
                    .ok_or(EvalError::Overflow)?;
            } else if self.take(b'-') {
                value = value
                    .checked_sub(self.parse_product()?)
                    .ok_or(EvalError::Overflow)?;
            } else {
                return Ok(value);
            }
        }
    }

    fn parse_product(&mut self) -> Result<i64, EvalError> {
        let mut value = self.parse_unary()?;
        loop {
            if self.take(b'*') {
                value = value
                    .checked_mul(self.parse_unary()?)
                    .ok_or(EvalError::Overflow)?;
            } else if self.take(b'/') {
                let divisor = self.parse_unary()?;
                if divisor == 0 {
                    return Err(EvalError::DivisionByZero);
                }
                value = value.checked_div(divisor).ok_or(EvalError::Overflow)?;
            } else {
                return Ok(value);
            }
        }
    }

    fn parse_unary(&mut self) -> Result<i64, EvalError> {
        if self.take(b'+') {
            self.parse_unary()
        } else if self.take(b'-') {
            self.parse_unary()?
                .checked_neg()
                .ok_or(EvalError::Overflow)
        } else {
            self.parse_atom()
        }
    }

    fn parse_atom(&mut self) -> Result<i64, EvalError> {
        self.skip_space();
        if self.take(b'(') {
            self.skip_space();
            if self.position == self.source.len() {
                return Err(EvalError::MissingClosingParen);
            }
            if self.source.get(self.position) == Some(&b')') {
                return Err(EvalError::UnexpectedToken(self.position));
            }
            let value = self.parse_sum()?;
            self.skip_space();
            match self.source.get(self.position) {
                Some(b')') => {
                    self.position += 1;
                    return Ok(value);
                }
                Some(_) => return Err(EvalError::UnexpectedToken(self.position)),
                None => return Err(EvalError::MissingClosingParen),
            }
        }

        self.skip_space();
        let start = self.position;
        let mut value = 0i64;
        let mut found = false;
        while let Some(byte @ b'0'..=b'9') = self.source.get(self.position).copied() {
            found = true;
            value = value
                .checked_mul(10)
                .and_then(|number| number.checked_add((byte - b'0') as i64))
                .ok_or(EvalError::Overflow)?;
            self.position += 1;
        }
        if found {
            Ok(value)
        } else {
            Err(EvalError::UnexpectedToken(start))
        }
    }
}

