#[path = "solution.rs"]
mod solution;

use solution::{evaluate, EvalError};

#[test]
fn evaluates_precedence_associativity_parentheses_and_unary_chains() {
    assert_eq!(evaluate("2 + 3 * 4"), Ok(14));
    assert_eq!(evaluate("(2 + 3) * 4"), Ok(20));
    assert_eq!(evaluate("20 / 3 / 2"), Ok(3));
    assert_eq!(evaluate("10 - 3 - 2"), Ok(5));
    assert_eq!(evaluate("---5 + ++2"), Ok(-3));
    assert_eq!(evaluate("7 / -2"), Ok(-3));
    assert_eq!(evaluate("1++2"), Ok(3));
}

#[test]
fn accepts_ascii_whitespace_without_mutating_input() {
    let source = String::from("\t ( 12\n- 2 ) *\r 3 ");
    let before = source.clone();
    assert_eq!(evaluate(&source), Ok(30));
    assert_eq!(source, before);
}

#[test]
fn handles_empty_and_operand_errors_at_precise_offsets() {
    assert_eq!(evaluate(""), Err(EvalError::EmptyExpression));
    assert_eq!(evaluate(" \t\n\r"), Err(EvalError::EmptyExpression));
    assert_eq!(evaluate("*1"), Err(EvalError::UnexpectedToken(0)));
    assert_eq!(evaluate("1 +"), Err(EvalError::UnexpectedToken(3)));
    assert_eq!(evaluate("()"), Err(EvalError::UnexpectedToken(1)));
    assert_eq!(evaluate("1 2"), Err(EvalError::UnexpectedToken(2)));
    assert_eq!(evaluate("1)"), Err(EvalError::UnexpectedToken(1)));
}

#[test]
fn reports_errors_inside_parentheses_at_the_first_offending_byte() {
    assert_eq!(evaluate("(1 2)"), Err(EvalError::UnexpectedToken(3)));
    assert_eq!(evaluate("((1 2))"), Err(EvalError::UnexpectedToken(4)));
    assert_eq!(evaluate("(1 a)"), Err(EvalError::UnexpectedToken(3)));
}

#[test]
fn reports_invalid_characters_using_byte_offsets() {
    assert_eq!(evaluate("1+a"), Err(EvalError::UnexpectedToken(2)));
    assert_eq!(evaluate("1+é"), Err(EvalError::UnexpectedToken(2)));
}

#[test]
fn distinguishes_missing_closing_parentheses() {
    assert_eq!(evaluate("("), Err(EvalError::MissingClosingParen));
    assert_eq!(evaluate("(1"), Err(EvalError::MissingClosingParen));
    assert_eq!(evaluate("((1)"), Err(EvalError::MissingClosingParen));
    assert_eq!(evaluate("(1 + 2"), Err(EvalError::MissingClosingParen));
}

#[test]
fn checks_literal_and_arithmetic_boundaries() {
    assert_eq!(evaluate("9223372036854775807"), Ok(i64::MAX));
    assert_eq!(
        evaluate("9223372036854775807 + 1"),
        Err(EvalError::Overflow)
    );
    assert_eq!(evaluate("-9223372036854775807 - 1"), Ok(i64::MIN));
    assert_eq!(
        evaluate("-(-9223372036854775807 - 1)"),
        Err(EvalError::Overflow)
    );
    assert_eq!(
        evaluate("3037000500 * 3037000500"),
        Err(EvalError::Overflow)
    );
}

#[test]
fn checks_division_errors_including_min_divided_by_negative_one() {
    assert_eq!(evaluate("10 / (3 - 3)"), Err(EvalError::DivisionByZero));
    assert_eq!(
        evaluate("(-9223372036854775807 - 1) / -1"),
        Err(EvalError::Overflow)
    );
}

