mod solution;

use solution::{emit_rust_models, GenerationError, Model, ModelType, Property};

fn property(name: &str, model_type: ModelType, required: bool) -> Property {
    Property {
        name: name.to_string(),
        model_type,
        required,
    }
}

#[test]
fn empty_input_emits_empty_output() {
    assert_eq!(emit_rust_models(&[]), Ok(String::new()));
}

#[test]
fn emits_all_mappings_order_and_exact_layout() {
    let models = vec![
        Model {
            name: "User".into(),
            properties: vec![
                property("name", ModelType::Text, true),
                property("age", ModelType::Integer, false),
                property("score", ModelType::Decimal, true),
                property("active", ModelType::Flag, true),
                property(
                    "aliases",
                    ModelType::Sequence(Box::new(ModelType::Text)),
                    false,
                ),
                property(
                    "index",
                    ModelType::Dictionary(Box::new(ModelType::Sequence(Box::new(
                        ModelType::Named("Address".into()),
                    )))),
                    true,
                ),
            ],
        },
        Model {
            name: "Address".into(),
            properties: vec![property("line", ModelType::Text, true)],
        },
    ];

