    assert_eq!(emit_rust_models(&models), Ok(expected.to_string()));
}

#[test]
fn accepts_forward_references_and_identifiers_defined_by_the_spec() {
    let models = vec![
        Model {
            name: "_".into(),
            properties: vec![property("type", ModelType::Named("struct".into()), true)],
        },
        Model {
            name: "struct".into(),
            properties: vec![],
        },
    ];

    let output = emit_rust_models(&models).unwrap();
    assert!(output.contains("pub struct _ {"));
    assert!(output.contains("    pub type: struct,"));
    assert!(output.contains("pub struct struct {"));
}

#[test]
fn rejects_invalid_model_property_and_reference_identifiers() {
    let bad_model = vec![Model {
        name: "9Bad".into(),
        properties: vec![],
    }];
    assert_eq!(
        emit_rust_models(&bad_model),
        Err(GenerationError::InvalidIdentifier("9Bad".into()))
    );

    let bad_property = vec![Model {
        name: "Good".into(),
        properties: vec![property("bad-name", ModelType::Text, true)],
    }];
    assert_eq!(
        emit_rust_models(&bad_property),
        Err(GenerationError::InvalidIdentifier("bad-name".into()))
    );

    let bad_reference = vec![Model {
        name: "Good".into(),
        properties: vec![property(
            "field",
            ModelType::Sequence(Box::new(ModelType::Named("Not.Valid".into()))),
            true,
        )],
    }];
    assert!(emit_rust_models(&bad_reference).is_err());
}

#[test]
fn detects_duplicate_models_and_properties_by_exact_name() {
    let duplicate_models = vec![
        Model {
            name: "A".into(),
            properties: vec![],
        },
        Model {
            name: "A".into(),
            properties: vec![],
        },
    ];
    assert_eq!(
        emit_rust_models(&duplicate_models),
        Err(GenerationError::DuplicateModel("A".into()))
    );

    let duplicate_properties = vec![Model {
        name: "A".into(),
        properties: vec![
            property("x", ModelType::Text, true),
            property("x", ModelType::Flag, false),
