#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Verb {
    Read,
    Write,
    Replace,
    Remove,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Packet {
    pub verb: Verb,
    pub route: String,
    pub attributes: Vec<(String, String)>,
    pub payload: Vec<u8>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TextPacket {
    pub verb: Verb,
    pub route: String,
    pub attributes: Vec<(String, String)>,
    pub payload: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ParseError {
    MissingSeparator,
    InvalidHeaderUtf8,
    InvalidStartLine,
    UnknownVerb,
    InvalidAttribute,
    InvalidBodyUtf8,
}

pub fn parse_packet(input: &[u8]) -> Result<Packet, ParseError> {
    let split = input
        .windows(2)
        .position(|window| window == b"\n\n")
        .ok_or(ParseError::MissingSeparator)?;
    let header = std::str::from_utf8(&input[..split])
        .map_err(|_| ParseError::InvalidHeaderUtf8)?;
    let mut lines = header.split('\n');
    let start_line = lines.next().ok_or(ParseError::InvalidStartLine)?;
    let mut start = start_line.split(' ');
    let verb_text = start.next().ok_or(ParseError::InvalidStartLine)?;
    let route = start
        .next()
        .filter(|value| !value.is_empty())
        .ok_or(ParseError::InvalidStartLine)?;
    if verb_text.is_empty() || start.next().is_some() {
        return Err(ParseError::InvalidStartLine);
    }
    let verb = match verb_text {
        "READ" => Verb::Read,
        "WRITE" => Verb::Write,
        "REPLACE" => Verb::Replace,
        "REMOVE" => Verb::Remove,
        _ => return Err(ParseError::UnknownVerb),
    };
    let mut attributes = Vec::new();
    for line in lines {
        let (name, value) = line.split_once(':').ok_or(ParseError::InvalidAttribute)?;
        if name.is_empty() {
            return Err(ParseError::InvalidAttribute);
        }
        attributes.push((name.to_owned(), value.to_owned()));
    }
    Ok(Packet {
        verb,
        route: route.to_owned(),
        attributes,
        payload: input[split + 2..].to_vec(),
    })
}

pub fn parse_text_packet(input: &[u8]) -> Result<TextPacket, ParseError> {
    let packet = parse_packet(input)?;
    let payload = String::from_utf8(packet.payload)
        .map_err(|_| ParseError::InvalidBodyUtf8)?;
    Ok(TextPacket {
        verb: packet.verb,
        route: packet.route,
        attributes: packet.attributes,
        payload,
    })
}

