#[path = "solution.rs"]
mod solution;

use solution::{parse_packet, parse_text_packet, Packet, ParseError, TextPacket, Verb};

fn binary_success(input: &[u8]) -> Packet {
    match parse_packet(input) {
        Ok(packet) => packet,
        Err(_) => panic!("binary packet should parse"),
    }
}

fn text_success(input: &[u8]) -> TextPacket {
    match parse_text_packet(input) {
        Ok(packet) => packet,
        Err(_) => panic!("text packet should parse"),
    }
}

#[test]
fn parses_binary_packet_and_preserves_attributes_and_payload() {
    let input = b"WRITE /items\nname:first\nname:second\nempty:\ncomplex:a:b:c\n\n\x00\xff\n\nend";
    let packet = binary_success(input);

    assert!(matches!(packet.verb, Verb::Write));
    assert_eq!(packet.route, "/items");
    assert_eq!(
        packet.attributes,
        vec![
            ("name".to_string(), "first".to_string()),
            ("name".to_string(), "second".to_string()),
            ("empty".to_string(), String::new()),
            ("complex".to_string(), "a:b:c".to_string()),
        ]
    );
    assert_eq!(packet.payload, b"\x00\xff\n\nend".to_vec());
}

#[test]
fn parses_each_verb_and_zero_attributes_or_empty_body() {
    for (word, expected) in [
        ("READ", 0),
        ("WRITE", 1),
        ("REPLACE", 2),
        ("REMOVE", 3),
    ] {
        let input = format!("{} /route\n\n", word);
        let packet = binary_success(input.as_bytes());
        let actual = match packet.verb {
            Verb::Read => 0,
            Verb::Write => 1,
            Verb::Replace => 2,
            Verb::Remove => 3,
        };
        assert_eq!(actual, expected);
        assert!(packet.attributes.is_empty());
        assert!(packet.payload.is_empty());
    }
}

#[test]
fn both_parsers_use_lf_framing_and_preserve_carriage_returns() {
    let input = b"READ /\nkey:value\r\nnext:kept\n\nbody";

    let binary = binary_success(input);
    assert!(matches!(binary.verb, Verb::Read));
    assert_eq!(binary.route, "/");
    assert_eq!(
        binary.attributes,
        vec![
            ("key".to_string(), "value\r".to_string()),
            ("next".to_string(), "kept".to_string()),
        ]
    );
    assert_eq!(binary.payload, b"body".to_vec());

    let text = text_success(input);
    assert!(matches!(text.verb, Verb::Read));
    assert_eq!(text.route, "/");
    assert_eq!(
        text.attributes,
        vec![
            ("key".to_string(), "value\r".to_string()),
            ("next".to_string(), "kept".to_string()),
        ]
    );
    assert_eq!(text.payload, "body");
}

#[test]
fn first_empty_line_is_the_separator_for_both_parsers() {
    let input = b"READ /r\n\nfirst\n\nsecond";

    let binary = binary_success(input);
    assert!(binary.attributes.is_empty());
    assert_eq!(binary.payload, b"first\n\nsecond".to_vec());

    let text = text_success(input);
    assert!(text.attributes.is_empty());
    assert_eq!(text.payload, "first\n\nsecond");
}

#[test]
fn binary_accepts_invalid_body_utf8_and_text_rejects_it() {
    assert!(matches!(
        parse_text_packet(b"READ /x\n\n\xff"),
        Err(ParseError::InvalidBodyUtf8)
    ));

    let packet = binary_success(b"READ /x\n\n\xff");
    assert_eq!(packet.payload, vec![0xff]);
}

#[test]
fn parsed_packets_own_their_data() {
    let mut binary_input = b"REMOVE /x\na:b\n\npayload".to_vec();
    let binary_before = binary_input.clone();
    let binary = binary_success(&binary_input);
    assert_eq!(binary_input, binary_before);
    binary_input.fill(b'x');
    assert!(matches!(binary.verb, Verb::Remove));
    assert_eq!(binary.route, "/x");
    assert_eq!(binary.attributes, vec![("a".into(), "b".into())]);
    assert_eq!(binary.payload, b"payload".to_vec());

    let mut text_input = b"REPLACE /text\nk:v\n\nhello \xF0\x9F\xA6\x80".to_vec();
    let text_before = text_input.clone();
    let text = text_success(&text_input);
    assert_eq!(text_input, text_before);
    text_input.fill(b'x');
    assert!(matches!(text.verb, Verb::Replace));
    assert_eq!(text.route, "/text");
    assert_eq!(text.attributes, vec![("k".into(), "v".into())]);
    assert_eq!(text.payload, "hello 🦀");
}

#[test]
fn reports_missing_separator() {
    assert!(matches!(
        parse_packet(b"READ /x\n"),
        Err(ParseError::MissingSeparator)
    ));
    assert!(matches!(
        parse_text_packet(b""),
        Err(ParseError::MissingSeparator)
    ));
}

#[test]
fn rejects_non_utf8_header() {
    assert!(matches!(
        parse_packet(b"READ /x\nname:\xff\n\nbody"),
        Err(ParseError::InvalidHeaderUtf8)
    ));
    assert!(matches!(
        parse_text_packet(b"R\xffAD /x\n\n"),
        Err(ParseError::InvalidHeaderUtf8)
    ));
}

#[test]
fn validates_start_line_shape_and_verb() {
    for input in [
        &b"READ\n\n"[..],
        &b"READ \n\n"[..],
        &b" READ /x\n\n"[..],
        &b"READ  /x\n\n"[..],
        &b"READ /x extra\n\n"[..],
        &b"READ\t/x\n\n"[..],
    ] {
        assert!(matches!(
            parse_packet(input),
            Err(ParseError::InvalidStartLine)
        ));
    }

    assert!(matches!(
        parse_packet(b"PATCH /x\n\n"),
        Err(ParseError::UnknownVerb)
    ));
}

#[test]
fn validates_attribute_lines_without_normalizing_valid_ones() {
    assert!(matches!(
        parse_packet(b"READ /x\nmissing-colon\n\n"),
        Err(ParseError::InvalidAttribute)
    ));
    assert!(matches!(
        parse_text_packet(b"READ /x\n:value\n\n"),
        Err(ParseError::InvalidAttribute)
    ));

    let packet = binary_success(b"READ /x\n x : value\n\n");
    assert_eq!(packet.attributes, vec![(" x ".into(), " value".into())]);
}

