#[path = "solution.rs"]
mod solution;

use solution::{create_rule, ordered_rules, update_rule, Channel, NoticeRule, RuleError, RulePatch};

fn created(id: u64, channels: Vec<Channel>, prefix: &str) -> NoticeRule {
    match create_rule(id, channels, prefix.to_string()) {
        Ok(rule) => rule,
        Err(_) => panic!("rule should be created"),
    }
}

fn update_ok(rule: &mut NoticeRule, patch: RulePatch) {
    match update_rule(rule, patch) {
        Ok(()) => {}
        Err(_) => panic!("rule update should succeed"),
    }
}

fn channel_code(channel: &Channel) -> u8 {
    match channel {
        Channel::Email => 0,
        Channel::Sms => 1,
        Channel::Dashboard => 2,
    }
}

#[derive(Debug, PartialEq, Eq)]
struct Snapshot {
    id: u64,
    channels: Vec<u8>,
    channels_ptr: usize,
    subject_prefix: String,
    subject_prefix_ptr: usize,
    expires_after: Option<u32>,
    tags: Option<Vec<String>>,
    tags_ptr: Option<usize>,
    tag_string_ptrs: Vec<usize>,
}

fn snapshot(rule: &NoticeRule) -> Snapshot {
    Snapshot {
        id: rule.id,
        channels: rule.channels.iter().map(channel_code).collect(),
        channels_ptr: rule.channels.as_ptr() as usize,
        subject_prefix: rule.subject_prefix.clone(),
        subject_prefix_ptr: rule.subject_prefix.as_ptr() as usize,
        expires_after: rule.expires_after,
        tags: rule.tags.clone(),
        tags_ptr: rule.tags.as_ref().map(|tags| tags.as_ptr() as usize),
        tag_string_ptrs: rule
            .tags
            .as_ref()
            .map(|tags| tags.iter().map(|tag| tag.as_ptr() as usize).collect())
            .unwrap_or_default(),
    }
}

#[test]
fn creates_rule_with_exact_prefix_and_unset_optional_fields() {
    let rule = created(
        7,
        vec![Channel::Email, Channel::Sms, Channel::Email],
        "  alerts  ",
    );

    assert_eq!(rule.id, 7);
    assert_eq!(rule.channels.len(), 3);
    assert!(matches!(rule.channels[0], Channel::Email));
    assert!(matches!(rule.channels[1], Channel::Sms));
    assert!(matches!(rule.channels[2], Channel::Email));
    assert_eq!(rule.subject_prefix, "  alerts  ");
    assert_eq!(rule.expires_after, None);
    assert_eq!(rule.tags, None);
}

#[test]
fn create_rule_validates_required_inputs() {
    assert!(matches!(
        create_rule(0, vec![Channel::Email], "ok".into()),
        Err(RuleError::InvalidId)
    ));
    assert!(matches!(
        create_rule(1, vec![], "ok".into()),
        Err(RuleError::NoChannels)
    ));
    assert!(matches!(
        create_rule(1, vec![Channel::Dashboard], " \t\n".into()),
        Err(RuleError::EmptyPrefix)
    ));
}

#[test]
fn patch_outer_none_preserves_and_inner_none_clears() {
    let mut rule = created(1, vec![Channel::Dashboard], "notice");
    update_ok(
        &mut rule,
        RulePatch {
            expires_after: Some(Some(30)),
            tags: Some(Some(vec!["ops".into(), "urgent".into()])),
        },
    );

    update_ok(
        &mut rule,
        RulePatch {
            expires_after: None,
            tags: None,
        },
    );
    assert_eq!(rule.expires_after, Some(30));
    assert_eq!(rule.tags, Some(vec!["ops".into(), "urgent".into()]));

    update_ok(
        &mut rule,
        RulePatch {
            expires_after: Some(None),
            tags: Some(None),
        },
    );
    assert_eq!(rule.expires_after, None);
    assert_eq!(rule.tags, None);
}

#[test]
fn empty_tag_vector_is_valid_and_tag_text_is_preserved() {
    let mut rule = created(2, vec![Channel::Sms], "p");
    update_ok(
        &mut rule,
        RulePatch {
            expires_after: Some(Some(u32::MAX)),
            tags: Some(Some(vec![])),
        },
    );
    assert_eq!(rule.expires_after, Some(u32::MAX));
    assert_eq!(rule.tags, Some(vec![]));

    update_ok(
        &mut rule,
        RulePatch {
            expires_after: None,
            tags: Some(Some(vec!["  tag  ".into()])),
        },
    );
    assert_eq!(rule.tags, Some(vec!["  tag  ".into()]));
}

#[test]
fn invalid_expiry_makes_multi_field_patch_atomic() {
    let mut rule = created(3, vec![Channel::Email], "prefix");
    update_ok(
        &mut rule,
        RulePatch {
            expires_after: Some(Some(10)),
            tags: Some(Some(vec!["old".into()])),
        },
    );
    let before = snapshot(&rule);

    assert!(matches!(
        update_rule(
            &mut rule,
            RulePatch {
                expires_after: Some(Some(0)),
                tags: Some(Some(vec!["new".into()])),
            }
        ),
        Err(RuleError::ZeroExpiry)
    ));
    assert_eq!(snapshot(&rule), before);
}

#[test]
fn invalid_tag_makes_expiry_change_atomic() {
    let mut rule = created(4, vec![Channel::Sms], "prefix");
    let before = snapshot(&rule);

    assert!(matches!(
        update_rule(
            &mut rule,
            RulePatch {
                expires_after: Some(Some(99)),
                tags: Some(Some(vec!["valid".into(), " \t".into()])),
            }
        ),
        Err(RuleError::EmptyTag)
    ));
    assert_eq!(snapshot(&rule), before);
}

#[test]
fn update_validates_each_required_field_in_the_proposed_rule_atomically() {
    let mut bad_id = created(5, vec![Channel::Email], "prefix");
    bad_id.id = 0;
    let bad_id_before = snapshot(&bad_id);
    assert!(matches!(
        update_rule(
            &mut bad_id,
            RulePatch {
                expires_after: Some(Some(9)),
                tags: None,
            }
        ),
        Err(RuleError::InvalidId)
    ));
    assert_eq!(snapshot(&bad_id), bad_id_before);

    let mut no_channels = created(6, vec![Channel::Sms], "prefix");
    no_channels.channels.clear();
    let no_channels_before = snapshot(&no_channels);
    assert!(matches!(
        update_rule(
            &mut no_channels,
            RulePatch {
                expires_after: Some(Some(9)),
                tags: None,
            }
        ),
        Err(RuleError::NoChannels)
    ));
    assert_eq!(snapshot(&no_channels), no_channels_before);

    let mut empty_prefix = created(7, vec![Channel::Dashboard], "prefix");
    empty_prefix.subject_prefix = " \t\n".into();
    let empty_prefix_before = snapshot(&empty_prefix);
    assert!(matches!(
        update_rule(
            &mut empty_prefix,
            RulePatch {
                expires_after: Some(Some(9)),
                tags: None,
            }
        ),
        Err(RuleError::EmptyPrefix)
    ));
    assert_eq!(snapshot(&empty_prefix), empty_prefix_before);
}

#[test]
fn clearing_invalid_existing_optional_fields_validates_the_proposed_state() {
    let mut zero_expiry = created(8, vec![Channel::Email], "prefix");
    zero_expiry.expires_after = Some(0);
    update_ok(
        &mut zero_expiry,
        RulePatch {
            expires_after: Some(None),
            tags: None,
        },
    );
    assert_eq!(zero_expiry.expires_after, None);

    let mut empty_tag = created(9, vec![Channel::Sms], "prefix");
    empty_tag.tags = Some(vec![" \t".into()]);
    update_ok(
        &mut empty_tag,
        RulePatch {
            expires_after: None,
            tags: Some(None),
        },
    );
    assert_eq!(empty_tag.tags, None);
}

#[test]
fn ordered_rules_is_stable_and_returns_original_references() {
    let rules = vec![
        created(2, vec![Channel::Email], "two-a"),
        created(1, vec![Channel::Sms], "one"),
        created(2, vec![Channel::Dashboard], "two-b"),
    ];
    let original_ids: Vec<u64> = rules.iter().map(|rule| rule.id).collect();

    let ordered = ordered_rules(&rules);
    assert_eq!(
        ordered.iter().map(|rule| rule.id).collect::<Vec<_>>(),
        vec![1, 2, 2]
    );
    assert!(std::ptr::eq(ordered[0], &rules[1]));
    assert!(std::ptr::eq(ordered[1], &rules[0]));
    assert!(std::ptr::eq(ordered[2], &rules[2]));
    assert_eq!(ordered[1].subject_prefix, "two-a");
    assert_eq!(ordered[2].subject_prefix, "two-b");
    assert_eq!(
        rules.iter().map(|rule| rule.id).collect::<Vec<_>>(),
        original_ids
    );

    let empty: Vec<NoticeRule> = vec![];
    assert!(ordered_rules(&empty).is_empty());
}

