use std::collections::HashSet;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProfileCard {
    pub code: String,
    pub label: String,
    pub summary: String,
    pub category: String,
}

fn trim_ascii(value: &str) -> &str {
    value.trim_matches(|c: char| c.is_ascii_whitespace())
}

pub fn parse_profile_card(input: &str) -> Result<ProfileCard, &'static str> {
    let mut code = None;
    let mut label = None;
    let mut summary = None;
    let mut category = None;
    let mut seen = HashSet::new();

    for raw in input.lines() {
        let line = trim_ascii(raw);
        if line.is_empty() {
            continue;
        }
        if line.matches('=').count() != 1 {
            return Err("malformed assignment");
        }
        let (key, value) = line.split_once('=').ok_or("malformed assignment")?;
        let key = trim_ascii(key);
        let value = trim_ascii(value);
        if key.is_empty() {
            return Err("empty key");
        }
        if !seen.insert(key.to_string()) {
            return Err("duplicate key");
        }
        match key {
            "code" => code = Some(value.to_string()),
            "label" => label = Some(value.to_string()),
            "summary" => summary = Some(value.to_string()),
            "category" => category = Some(value.to_string()),
            _ => {}
        }
    }

    Ok(ProfileCard {
        code: code.ok_or("missing code")?,
        label: label.ok_or("missing label")?,
        summary: summary.ok_or("missing summary")?,
        category: category.ok_or("missing category")?,
    })
}

