#[path = "solution.rs"]
mod solution;

use solution::{parse_profile_card, ProfileCard};

#[test]
fn parses_required_fields_in_any_order_and_trims_ascii_whitespace() {
    let input = "\n category = tools \n\tlabel= Forge \t\nsummary = Builds things\ncode = F01\n";
    assert_eq!(
        parse_profile_card(input),
        Ok(ProfileCard {
            code: "F01".into(),
            label: "Forge".into(),
            summary: "Builds things".into(),
            category: "tools".into(),
        })
    );
}

#[test]
fn trims_ascii_tabs_and_form_feeds_around_keys_and_values() {
    let input = "\tcode\x0c=\x0cC1\t\nlabel=L\nsummary=S\ncategory=K";
    let card = parse_profile_card(input).unwrap();
    assert_eq!(card.code, "C1");
    assert_eq!(card.label, "L");
    assert_eq!(card.summary, "S");
    assert_eq!(card.category, "K");
}

#[test]
fn accepts_empty_required_values_and_ignores_unique_unknown_keys() {
    let input = "unknown=anything\ncode=\nlabel=\nsummary=\ncategory=\nother=a value";
    assert_eq!(
        parse_profile_card(input),
        Ok(ProfileCard {
            code: String::new(),
            label: String::new(),
            summary: String::new(),
            category: String::new(),
        })
    );
}

#[test]
fn preserves_literal_values_after_ascii_only_trimming() {
    let input = "code=a b\nlabel=\u{2003}Forge\u{2003}\nsummary=\u{00a0}\ncategory=c\n未知=ignored";
    let card = parse_profile_card(input).unwrap();
    assert_eq!(card.code, "a b");
    assert_eq!(card.label, "\u{2003}Forge\u{2003}");
    assert_eq!(card.summary, "\u{00a0}");
    assert_eq!(card.category, "c");
}

#[test]
fn rejects_empty_blank_and_missing_required_fields() {
    assert!(parse_profile_card("").is_err());
    assert!(parse_profile_card(" \t\n\r\n\x0c\n").is_err());
    assert!(parse_profile_card("code=c\nlabel=l\nsummary=s").is_err());
}

#[test]
fn rejects_malformed_assignment_lines() {
    let valid_tail = "\ncode=c\nlabel=l\nsummary=s\ncategory=k";
    for bad_line in ["no assignment", "=value", "  = value", "x=a=b", "code=a=b"] {
        let input = format!("{}{}", bad_line, valid_tail);
        assert!(parse_profile_card(&input).is_err(), "accepted {bad_line:?}");
    }
}

#[test]
fn rejects_duplicate_required_and_unknown_keys() {
    assert!(parse_profile_card(
        "code=a\nlabel=l\ncode=b\nsummary=s\ncategory=c"
    )
    .is_err());
    assert!(parse_profile_card(
        "x=1\ncode=a\nlabel=l\nx=2\nsummary=s\ncategory=c"
    )
    .is_err());
}

#[test]
fn unicode_prefixed_required_name_is_an_unknown_key() {
    let missing_actual_code = "\u{2003}code=shadow\nlabel=l\nsummary=s\ncategory=k";
    assert!(parse_profile_card(missing_actual_code).is_err());

    let with_actual_code =
        "\u{2003}code=shadow\ncode=c\nlabel=l\nsummary=s\ncategory=k";
    let card = parse_profile_card(with_actual_code).unwrap();
    assert_eq!(card.code, "c");

    let duplicate_unknown =
        "\u{2003}code=one\ncode=c\n\u{2003}code=two\nlabel=l\nsummary=s\ncategory=k";
    assert!(parse_profile_card(duplicate_unknown).is_err());
}

#[test]
fn key_identity_is_literal_after_trimming() {
    let input = "Code=ignored\ncode=c\nlabel=l\nsummary=s\ncategory=k";
    let card = parse_profile_card(input).unwrap();
    assert_eq!(card.code, "c");

    let distinct_unknowns = "X=1\nx=2\ncode=c\nlabel=l\nsummary=s\ncategory=k";
    assert!(parse_profile_card(distinct_unknowns).is_ok());
}

#[test]
fn input_is_not_mutated_and_result_owns_copies() {
    let mut input = String::from("code=c\nlabel=l\nsummary=s\ncategory=k");
    let before = input.clone();
    let card = parse_profile_card(&input).unwrap();
    assert_eq!(input, before);

    input.clear();
    assert_eq!(card.code, "c");
    assert_eq!(card.label, "l");
    assert_eq!(card.summary, "s");
    assert_eq!(card.category, "k");
}

