#[path = "solution.rs"]
mod solution;

use solution::{lookup_setting, LookupError};

#[test]
fn rejects_empty_lookup_key_after_ascii_trimming() {
    let entries = vec![("key".to_string(), "value".to_string())];
    assert_eq!(lookup_setting(&entries, ""), Err(LookupError::EmptyKey));
    assert_eq!(
        lookup_setting(&entries, " \t\n\r"),
        Err(LookupError::EmptyKey)
    );
}

#[test]
fn matches_trimmed_keys_case_insensitively_and_returns_owned_trimmed_value() {
    let mut entries = vec![
        (" other ".to_string(), "ignored".to_string()),
        ("  FoO  ".to_string(), "\t first value \n".to_string()),
        ("foo".to_string(), "first value".to_string()),
    ];
    let before = entries.clone();
    let value = lookup_setting(&entries, "  fOo ").unwrap().unwrap();
    assert_eq!(value, "first value");
    assert_eq!(entries, before);

    entries[1].1.clear();
    assert_eq!(value, "first value");
}

#[test]
fn permits_empty_values_and_returns_none_without_a_match() {
    let entries = vec![("key".to_string(), " \t".to_string())];
    assert_eq!(lookup_setting(&entries, "KEY"), Ok(Some(String::new())));
    assert_eq!(lookup_setting(&entries, "missing"), Ok(None));
    assert_eq!(lookup_setting(&[], "valid"), Ok(None));
}

#[test]
fn permits_repeated_matches_only_when_trimmed_values_are_identical() {
    let same = vec![
        ("A".into(), " value ".into()),
        ("a".into(), "value\t".into()),
        ("a".into(), " value".into()),
    ];
    assert_eq!(lookup_setting(&same, "a"), Ok(Some("value".into())));

    let conflict = vec![
        ("A".into(), "value".into()),
        ("a".into(), "Value".into()),
    ];
    assert_eq!(
        lookup_setting(&conflict, "a"),
        Err(LookupError::ConflictingValues)
    );
}

#[test]
fn validates_every_entry_even_after_a_match_or_conflict() {
    let after_match = vec![
        ("key".into(), "value".into()),
        ("other".into(), "x".into()),
        ("   ".into(), "bad".into()),
    ];
    assert_eq!(
        lookup_setting(&after_match, "key"),
        Err(LookupError::MalformedEntry { index: 2 })
    );

    let after_conflict = vec![
        ("key".into(), "one".into()),
        ("KEY".into(), "two".into()),
        ("bad\u{7f}key".into(), "x".into()),
    ];
    assert_eq!(
        lookup_setting(&after_conflict, "key"),
        Err(LookupError::MalformedEntry { index: 2 })
    );
}

#[test]
fn reports_first_malformed_entry_in_input_order() {
    let leading_tab_is_trimmed = vec![
        ("good".into(), "v".into()),
        ("\ttrimmed-key".into(), "v".into()),
        (String::new(), "v".into()),
    ];
    assert_eq!(
        lookup_setting(&leading_tab_is_trimmed, "missing"),
        Err(LookupError::MalformedEntry { index: 2 })
    );

    let interior_control_comes_first = vec![
        ("good".into(), "v".into()),
        ("bad\tkey".into(), "v".into()),
        ("   ".into(), "v".into()),
    ];
    assert_eq!(
        lookup_setting(&interior_control_comes_first, "missing"),
        Err(LookupError::MalformedEntry { index: 1 })
    );
}

#[test]
fn boundary_ascii_whitespace_is_trimmed_but_interior_controls_are_malformed() {
    let valid = vec![("\t key \t".into(), " value ".into())];
    assert_eq!(lookup_setting(&valid, "key"), Ok(Some("value".into())));

    for key in ["ke\ty", "ke\ny", "ke\u{0}y", "ke\u{7f}y"] {
        let entries = vec![(key.to_string(), "value".to_string())];
        assert_eq!(
            lookup_setting(&entries, "key"),
            Err(LookupError::MalformedEntry { index: 0 })
        );
    }
}

#[test]
fn comparisons_are_ascii_only() {
    let entries = vec![("Ä".to_string(), "upper".to_string())];
    assert_eq!(lookup_setting(&entries, "ä"), Ok(None));
}

